        screenFrame.strokeRect(screenX, screenY, screenWidth, screenHeight);
        // Corner decorations
        screenFrame.fillStyle(0x666666);
        const cornerSize = 15;
        screenFrame.fillRect(screenX - 5, screenY - 5, cornerSize, 3);
