            // Apply hitbox from hitbox-config.js only for P2
            if (typeof hitboxConfig !== 'undefined' && hitboxConfig.loaded) {
                const config = hitboxConfig.hitboxes[this.p2Character] || hitboxConfig.hitboxes['wizard'];
                if (config && config.width && config.height) {
                    // Apply hitbox directly - no scale division
                    // Sprite editor saves in unscaled coordinates
                    this.wizard2.body.setSize(config.width, config.height);
                    
                    // Adjust offset for flipped sprites
                    let adjustedOffsetX = config.offsetX || 0;
                    if (this.wizard2.flipX) {
                        // When flipped horizontally, adjust the X offset
                        const frameWidth = this.wizard2.frame.width;
                        adjustedOffsetX = frameWidth - config.width - (config.offsetX || 0);
                    }
                    this.wizard2.body.setOffset(adjustedOffsetX, config.offsetY || 0);
                    hitboxApplied = true;
                }
            }
            // If still no hitbox, use default
            if (!hitboxApplied) {
                this.wizard2.body.setSize(30, 30);
                this.wizard2.body.setOffset(0, 0);
                }
            // Create shadow for P2
            this.createShadowFor(this.wizard2, 25, 12);
            // Set initial texture frame to prevent errors
            this.wizard2.setFrame(0);
            
            // Apply flips for P2 AFTER frame is set
            if (typeof hitboxConfig !== 'undefined' && hitboxConfig.loaded) {
                if (hitboxConfig.flips && hitboxConfig.flips[p2Char]) {
                    const flipData = hitboxConfig.flips[p2Char];
                    if (flipData.flipX !== undefined) {
                        this.wizard2.setFlipX(flipData.flipX);
                    }
                    if (flipData.flipY !== undefined) {
                        this.wizard2.setFlipY(flipData.flipY);
                    }
                }
            }
            
            // Initialize direction tracking for P2
            this.wizard2.directionBuffer = [];
            this.wizard2.lastStableDirection = 'down';
            // Initialize P2 properties
            this.wizard2.charges = [];
            this.wizard2.chargeSlots = new Array(8).fill(null);
            // Character-specific charge slots for P2
            this.wizard2.maxCharges = (this.p2Character === 'orb') ? 4 : 
                                       (this.p2Character === 'blip') ? 5 : 3;
            this.wizard2.currentChargeIndex = 0;
            this.wizard2.elementTiers = new Map(); // Track element tiers
            this.wizard2.chargeGroups = []; // For grouping linked charges
            this.wizard2.elementPouch = []; // Initialize pouch for storing elements
            // Element mastery for P2 wizard
