            this.playerLabel3.setOrigin(0.5);
            this.playerLabel3.setDepth(11);
            this.playerArrow3 = this.add.triangle(0, -80,
                0, 0,    // top point
                -8, 12,  // bottom left
                8, 12,   // bottom right
                0xffff00 // Yellow
            );
