    startGame() {
        // SAFETY: Force unpause if somehow still paused
        if (this.time.timeScale === 0 || this.gamePaused) {
            console.error('=== GAME WAS PAUSED AT STARTGAME! FORCING UNPAUSE ===');
            this.gamePaused = false;
            this.pauseSource = null;
            this.time.timeScale = 1;
            this.physics.resume();
            this.tweens.resumeAll();
        }
        // Enable player controls
        this.gameStarted = true;
        // Spawn random barrels at game start
        this.spawnRandomBarrels();
        // Set up periodic barrel spawning (every 30-60 seconds)
        this.barrelSpawnTimer = this.time.addEvent({
            delay: Phaser.Math.Between(30000, 60000), // 30-60 seconds
            callback: () => {
                // Spawn 1-3 new barrels
                const numBarrels = Phaser.Math.Between(1, 3);
                for (let i = 0; i < numBarrels; i++) {
                    const angle = Math.random() * Math.PI * 2;
                    const distance = Phaser.Math.Between(300, 600);
                    const x = this.wizard.x + Math.cos(angle) * distance;
                    const y = this.wizard.y + Math.sin(angle) * distance;
                    // Make sure barrel doesn't spawn too close to player
                    const distToPlayer = Phaser.Math.Distance.Between(x, y, this.wizard.x, this.wizard.y);
                    if (distToPlayer > 200) {
                        this.spawnBarrel(x, y);
                    }
                }
                // Reset timer for next spawn
                this.barrelSpawnTimer.delay = Phaser.Math.Between(30000, 60000);
            },
            loop: true
        });
        // Update charge UI with starting element (don't reset charges)
        this.updateChargeUI();
        // Set up camera to follow both players in multiplayer
        if (this.multiplayerEnabled && this.wizard2) {
            // Create a target point that follows midpoint between players
            this.cameraTarget = this.add.rectangle(0, 0, 1, 1, 0x000000, 0);
            this.cameraTarget.setDepth(-1);
            // Camera follows the target point
            this.cameras.main.startFollow(this.cameraTarget, true, 0.1, 0.1);
            // Store viewport dimensions for boundary calculations
            this.viewportWidth = 800;
            this.viewportHeight = 600;
            // Initialize P2's charge UI
            this.updateP2ChargeUI();
        } else {
            // Single player - normal camera follow
            this.cameras.main.startFollow(this.wizard, true, 0.1, 0.1);
        }
        // Initialize wave system
        this.waveStartTime = this.time.now;
        this.startNewWave();
        // Spireland-specific setup after everything is initialized
        if (this.stage === 'spire') {
            this.setupSpireland();
        }
        // Spawn dungeon gate for non-spire stages in single player mode
        // In co-op mode, it will spawn when a player dies
        if (this.stage !== 'spire' && this.stage !== 'nexus' && !this.multiplayerEnabled) {
            this.spawnDungeonGate();
        }
        // Mark animations as ready to prevent errors
        this.animationsReady = true;
        // updateChargeUI should handle all the display updates now
        // Force a UI update after game starts
        this.time.delayedCall(100, () => {
            this.updateChargeUI();
            // Auto-activate philosopher stone if needed
            if (this.shouldAutoActivatePhilosopherStone) {
                this.createPhilosopherStone();
                this.shouldAutoActivatePhilosopherStone = false;
            }
        });
        // CRITICAL: Add periodic checks for first 3 seconds to ensure game stays unpaused
        let checkCount = 0;
        const unpauseCheckInterval = setInterval(() => {
            checkCount++;
            // Only check if no legitimate pause sources
            if (!this.isPaused && !this.spellbookOpen && !this.chestSelectionActive && 
                !this.fusionUI && (!this.hitboxEditor || !this.hitboxEditor.enabled)) {
                if (this.time.timeScale === 0 || this.gamePaused) {
                    console.error(`=== GAME BECAME PAUSED! Check #${checkCount}, forcing unpause ===`);
                    this.gamePaused = false;
                    this.pauseSource = null;
                    this.time.timeScale = 1;
                    this.physics.resume();
                    this.tweens.resumeAll();
                }
            }
            // Stop checking after 3 seconds (30 checks)
            if (checkCount >= 30) {
                clearInterval(unpauseCheckInterval);
                }
        }, 100); // Check every 100ms
    }
